import{_ as o,c as t,o as d,a1 as l}from"./chunks/framework.C3Hmo1as.js";const p=JSON.parse('{"title":"Code Agent 自动化范式","description":"告别手动盯盘：AI 编程 Agent 的三大自动化范式","frontmatter":{"title":"Code Agent 自动化范式","description":"告别手动盯盘：AI 编程 Agent 的三大自动化范式","date":"2026-10-02T00:00:00.000Z","tags":["LangChain","/loop","/goal","/schedule"]},"headers":[],"relativePath":"ai/ai-coding-agent-automation-loops.md","filePath":"ai/ai-coding-agent-automation-loops.md"}'),a={name:"ai/ai-coding-agent-automation-loops.md"};function s(n,e,c,r,i,g){return d(),t("div",null,[...e[0]||(e[0]=[l('<p>在使用 AI 编程工具时，我们大多数时候仍处于“一问一答”的被动模式：下达指令、盯着屏幕等它改完、手动跑一下测试、把报错贴回去让它继续改，或者守着终端干等 CI 流水线跑完。</p><p>随着 Claude Code、OpenAI Codex、Cursor 等工具的演进，AI Agent 正在从“结对编程助手”向“自主值班工程师”跨越。以 Claude Code 中的三个核心指令——<code>/goal</code>、<code>/loop</code> 和 <code>/schedule</code> 为切入点，我们可以清晰地看懂现代 AI 编程 Agent 最核心的三大自动化工程范式：<strong>目标闭环（Verification Loop）</strong>、<strong>会话心跳（Session Heartbeat）</strong> 与 <strong>云端例程（Cloud Routines）</strong>。</p><h2 id="一、从-claude-code-看懂三大自动化指令" tabindex="-1">一、从 Claude Code 看懂三大自动化指令 <a class="header-anchor" href="#一、从-claude-code-看懂三大自动化指令" aria-label="Permalink to &quot;一、从 Claude Code 看懂三大自动化指令&quot;">​</a></h2><p>在日常研发中，“让 AI 自己跑起来”其实对应着三种截然不同的工程诉求。Claude Code 将它们拆解为了三个显式的斜杠指令：</p><table tabindex="0"><thead><tr><th>指令</th><th>核心定位</th><th>驱动逻辑</th><th>运行环境与生命周期</th><th>底层停止机制</th></tr></thead><tbody><tr><td><code>/goal</code></td><td>目标执行器(不达目的不罢休)</td><td>条件驱动：消除回合停顿，上一轮结束立即开启下一轮</td><td>本地当前 CLI 会话（支持跨中断恢复）</td><td>独立小模型裁判（Stop Hook）：每轮结束后由 Haiku 模型评估是否达标</td></tr><tr><td><code>/loop</code></td><td>本地轮询器(开着终端帮我盯梢)</td><td>时间驱动（本地）：按固定周期或由 AI 动态延迟（1m~1h）唤醒</td><td>本地当前 CLI 会话（终端关闭即失效，最长 7 天过期）</td><td>满足提示词条件后调用 <code>ScheduleWakeup(stop: true)</code> 自停，或按 <code>Esc</code> 中断</td></tr><tr><td><code>/schedule</code></td><td>云端例程 Routines(把电脑关了也能跑)</td><td>时间 / 事件驱动（云端）：定时（最小 1h）、GitHub 事件或 API 触发</td><td>Anthropic 托管云容器（每次从 GitHub 克隆仓库拉起新会话，永久常驻）</td><td>单次拉起的云端会话执行完毕即止；例程本身持续等待下一次触发</td></tr></tbody></table><h3 id="_1-goal-条件驱动的-连续攻坚战" tabindex="-1">1. <code>/goal</code>：条件驱动的“连续攻坚战” <a class="header-anchor" href="#_1-goal-条件驱动的-连续攻坚战" aria-label="Permalink to &quot;1. `/goal`：条件驱动的“连续攻坚战”&quot;">​</a></h3><p>当你面对一个确定性目标（如大规模重构、模块迁移、修完所有单测报错），不需要中间停顿，只需要 AI 马不停蹄地连续迭代时，使用 <code>/goal</code>。</p><ul><li><strong>工作原理：</strong> 它是会话级的 <strong>Stop Hook 包装器</strong>。每当主模型完成一轮修改，系统会自动将“当前进展 + 目标条件”发给独立的轻量级裁判模型（如 Haiku）。若裁判判定“未达成”，会将原因作为反馈塞回主模型，立即启动下一轮。</li><li><strong>实战示例：</strong></li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal 将所有旧版请求模块迁移至新 API，直到全部调用点编译通过且 pytest 退出码为 0，期间不得修改任何测试文件。</span></span></code></pre></div><h3 id="_2-loop-陪伴当前开发的-临时值班员" tabindex="-1">2. <code>/loop</code>：陪伴当前开发的“临时值班员” <a class="header-anchor" href="#_2-loop-陪伴当前开发的-临时值班员" aria-label="Permalink to &quot;2. `/loop`：陪伴当前开发的“临时值班员”&quot;">​</a></h3><p>当你正在本地开发，手头有一个异步状态（如刚提了 PR 等待 CI 结果、刚发版需要盯紧线上错误日志）需要隔几分钟看一眼时，用 <code>/goal</code> 会造成无意义的死循环空转，此时应使用 <code>/loop</code>。</p><ul><li><strong>4 种实用调用模式：</strong></li><li><strong>动态间隔（最推荐）：</strong> <code>/loop 检查当前分支 PR 状态，CI 挂了就拉取日志修复并推送，全绿且无新评论则停止循环</code>（省略时间，Claude 会在 1 分钟到 1 小时之间智能调整检查频率）。</li><li><strong>固定间隔：</strong> <code>/loop 5m 运行 ssh prod &#39;tail -100 /var/log/error.log&#39;，发现新 ERROR 则定位原因，连续 6 次正常则停止</code>。</li><li><strong>嵌套技能：</strong> <code>/loop 30m /review-pr 1234</code>（周期性调用其他斜杠技能）。</li><li><strong>自定义值班清单（<code>.claude/loop.md</code>）：</strong> 在项目下配置 <code>.claude/loop.md</code> 定义常规巡检动作（查 CI、查未处理异常、领 TODO 任务），平时只需敲入 <code>/loop</code> 即可进入自动值班状态，且修改文件后在下一轮立即热生效。</li></ul><h3 id="_3-schedule-脱离本地的-7×24-云端流水线" tabindex="-1">3. <code>/schedule</code>：脱离本地的“7×24 云端流水线” <a class="header-anchor" href="#_3-schedule-脱离本地的-7×24-云端流水线" aria-label="Permalink to &quot;3. `/schedule`：脱离本地的“7×24 云端流水线”&quot;">​</a></h3><p><code>/loop</code> 绑死在本地终端进程上，合上笔记本就会中断。如果需要跨天常驻、团队共享或响应外部 Webhook，则使用 <code>/schedule</code>（对应官方的 <strong>Routines</strong> 功能）。</p><ul><li><strong>工作原理：</strong> 任务运行在云端隔离容器中，自动克隆 GitHub 仓库并加载预配置的 MCP 连接器（Slack、Jira、Sentry 等）。</li><li><strong>典型场景：</strong> 每天早上 8 点自动汇总过去 24 小时的新 Issue 并分配标签；或每周五自动扫描本周合并的 PR，检测 API 变动并提交文档更新 PR。</li></ul><h2 id="二、横向对比-其他主流-code-agent-是如何实现的" tabindex="-1">二、横向对比：其他主流 Code Agent 是如何实现的？ <a class="header-anchor" href="#二、横向对比-其他主流-code-agent-是如何实现的" aria-label="Permalink to &quot;二、横向对比：其他主流 Code Agent 是如何实现的？&quot;">​</a></h2><p>这三种能力并非 Claude Code 独有，它们在 <strong>OpenAI Codex</strong>、<strong>Cursor</strong>、<strong>Aider</strong> 和 <strong>OpenClaw</strong> 等主流工具中有着清晰的架构映射，只是各家在“交互入口”与“本地/云端重心”上取舍不同：</p><table tabindex="0"><thead><tr><th style="text-align:left;">自动化范式</th><th style="text-align:left;">Claude Code</th><th style="text-align:left;">OpenAI Codex (CLI + Cloud)</th><th style="text-align:left;">Cursor (IDE + Cloud)</th><th style="text-align:left;">Aider / OpenClaw (极客/开源框架)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. 目标验证闭环</strong><br><br>(Verification Loop)</td><td style="text-align:left;"><code>/goal</code> 指令<br><br>（内置独立裁判模型每轮验收）</td><td style="text-align:left;">内化为底层默认行为<br><br>（CLI 的 <code>--full-auto</code> 模式，或 Cloud 沙箱内跑通测试才交卷）</td><td style="text-align:left;">Agent Mode + Auto-run<br><br>（自动捕获终端与 Lint 报错并持续修复）</td><td style="text-align:left;">Aider <code>--auto-test</code><br><br>（测试退出码非 0 则将报错塞回模型重修）</td></tr><tr><td style="text-align:left;"><strong>2. 会话心跳轮询</strong><br><br>(Session Heartbeat)</td><td style="text-align:left;"><code>/loop</code> + <code>loop.md</code><br><br>（保持当前会话上下文定时唤醒）</td><td style="text-align:left;">无原生 CLI 轮询命令<br><br>（需靠外部 <code>watch</code> 包裹 <code>codex -q</code> 静默模式）</td><td style="text-align:left;">无本地定时器<br><br>（鼓励直接转交云端 Background Agent）</td><td style="text-align:left;">OpenClaw <code>Heartbeat</code><br><br>（读取 <code>HEARTBEAT.md</code> 在主会话定时注入指令）</td></tr><tr><td style="text-align:left;"><strong>3. 云端异步调度</strong><br><br>(Cloud Cron / Background)</td><td style="text-align:left;"><code>/schedule</code> <strong>(Routines)</strong><br><br>（云容器克隆仓库，定时/事件/API 触发）</td><td style="text-align:left;">Codex Cloud + Automations<br><br>（多容器高并发并行跑任务，支持定时与事件触发）</td><td style="text-align:left;">Background Agents<br><br>（云端 VM 隔离分支，支持 Slack <code>@cursor</code> 触发与无头浏览器录屏验证）</td><td style="text-align:left;">OpenClaw <code>cron</code><br><br>（独立隔离会话定时任务；Aider 需挂载 GitHub Actions）</td></tr></tbody></table><h3 id="核心设计哲学差异-claude-code-vs-openai-codex" tabindex="-1">核心设计哲学差异：Claude Code vs. OpenAI Codex <a class="header-anchor" href="#核心设计哲学差异-claude-code-vs-openai-codex" aria-label="Permalink to &quot;核心设计哲学差异：Claude Code vs. OpenAI Codex&quot;">​</a></h3><p>对比表格可以发现一个非常有趣的架构分野：</p><ul><li><strong>Claude Code 是“自下而上（CLI-First）”：</strong> 它先把本地终端的能力武装到牙齿，让你能细腻地控制当前会话是“连续攻坚（<code>/goal</code>）”还是“定时打盹（<code>/loop</code>）”，然后再通过 <code>/schedule</code> 把能力延伸到云端。</li><li><strong>OpenAI Codex 是“自上而下（Cloud-First）”：</strong> Codex 从设计之初就主打<strong>云端异步委派</strong>。在 Codex Cloud 中，“跑通测试才交卷（<code>/goal</code>）”是沙箱的出厂默认行为；遇到耗时任务或需要盯盘的场景，OpenAI 认为你应该直接派发给云端容器在后台跑（对应 <code>/schedule</code>），因此 Codex CLI 干脆省略了本地 <code>/loop</code> 命令。如果在本地必须用 Codex CLI 做轮询，通常需要借助系统级 <code>watch</code> 命令组合：</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;codex -q --full-auto &#39;检查当前分支 CI 状态，若失败则拉取日志尝试修复&#39;&quot;</span></span></code></pre></div><ul><li><strong>OpenClaw 的命名巧合：</strong> 在开源框架中，OpenClaw 的设计与 Claude Code 最为神似——它的 <code>Heartbeat</code>（配合 <code>HEARTBEAT.md</code>）完美对应 <code>/loop</code>（配合 <code>loop.md</code>），用于在保持上下文的主会话中做轻量巡检；而它的 <code>Cron</code> 则对应 <code>/schedule</code>，用于拉起干净的独立会话跑定时重任务。</li></ul><h2 id="三、实战进阶-组合拳打造-无人值守研发流水线" tabindex="-1">三、实战进阶：组合拳打造“无人值守研发流水线” <a class="header-anchor" href="#三、实战进阶-组合拳打造-无人值守研发流水线" aria-label="Permalink to &quot;三、实战进阶：组合拳打造“无人值守研发流水线”&quot;">​</a></h2><p>真正高效的工程实践，不是孤立地使用某一个指令，而是将它们<strong>嵌套串联</strong>起来。以下是经过实战检验的“四层自动化组合拳”：</p><ol><li><strong>触发层（<code>/schedule</code> 云端定时唤醒）：</strong> 配置云端 Routine，每小时扫描一次项目的 Bug 反馈渠道或新增 Issue。</li><li><strong>控制层（<code>/goal</code> 设定本轮清空条件）：</strong> 在唤醒提示词中挂载 <code>/goal</code>——<em>“本轮发现的每一条可复现 Bug，必须完成复现单测编写、代码修复且测试全部通过后才允许结束会话”</em>。</li><li><strong>规范层（<code>SKILL.md</code> / <code>CLAUDE.md</code> / <code>AGENTS.md</code> 量化标准）：</strong> 将团队的代码规范、测试命令和“什么叫修好了”的验收标准写入项目级规范文件，给裁判模型提供明确的判断依据。</li><li><strong>权限层（开启 <code>Auto Mode</code> / <code>--full-auto</code>）：</strong> 消除单轮内部工具调用的人工确认弹窗，让 Agent 在沙箱或受控分支内一气呵成并最终提交 PR。</li></ol><h2 id="四、落地避坑指南" tabindex="-1">四、落地避坑指南 <a class="header-anchor" href="#四、落地避坑指南" aria-label="Permalink to &quot;四、落地避坑指南&quot;">​</a></h2><p>在将这些自动化循环引入日常开发前，务必注意以下三个工程边界：</p><ul><li><strong>警惕“Token 刺客”，必写退出条件：</strong> 无论是 <code>/loop</code> 还是 <code>/goal</code>，如果目标模糊或缺少终止条件，极易陷入死循环（例如 <code>/loop</code> 固定间隔默认长达 7 天才过期）。在提示词中务必加上明确的熔断条件（如*“部署成功后停止循环”<em>或</em>“若连续尝试修复 3 次仍失败，立即停止并输出诊断报告”*）。</li><li><strong>给裁判模型提供“客观信号”：</strong> 在使用 <code>/goal</code> 或 Codex <code>--full-auto</code> 时，不要写“把代码优化得更优雅”这种主观目标，而要给可执行的命令信号（如 <code>pytest 退出码为 0</code>、<code>tsc --noEmit 无报错</code>、<code>git diff 行数小于 200</code>）。</li><li><strong>本地长时挂机配合 <code>tmux</code>：</strong> 像 <code>/loop</code> 这类会话级指令依赖终端进程存活。如果需要在本地开发机或跳板机上长时间运行，务必将其放入 <code>tmux</code> 或 <code>screen</code> 会话中，防止网络抖动或终端关闭导致值班中断。</li></ul><p>掌握了 <strong>目标闭环（Goal）</strong>、<strong>会话心跳（Loop）</strong> 和 <strong>云端调度（Schedule）</strong> 这三把钥匙，无论你手头使用的是 Claude Code、Codex 还是其他自研 Agent 框架，都能真正把重复的“盯盘与试错”交给机器，将精力集中在核心架构与业务决策上。</p>',30)])])}const h=o(a,[["render",s]]);export{p as __pageData,h as default};
